"""One full order on the test copy: taken at the counter, priced and confirmed, deposit, slip printed, made in the kitchen,
balance taken, handed over. Invented data only; nothing reaches the real database or any customer."""
import asyncio, pathlib, sys, re
from playwright.async_api import async_playwright
HERE = pathlib.Path(__file__).parent; OUT = HERE / "shotsJourney"; OUT.mkdir(exist_ok=True)
for f in OUT.glob('*.png'): f.unlink()
SRC = sys.argv[1] if len(sys.argv) > 1 else "hosted-staff.html"
PAGE = "hosted-journey.html"
(HERE / PAGE).write_text((HERE / SRC).read_text().replace('<script src="mock.js"></script>', '<script src="mock.js"></script>\n<script src="journey_overlay.js"></script>'))
R = []; N = [0]
def check(n, ok, d=''):
    R.append(bool(ok)); print(('PASS ' if ok else 'FAIL ') + n + (' -> ' + str(d)[:300] if not ok and d != '' else ''))
async def shot(pg, name, full=False):
    N[0] += 1; await pg.wait_for_timeout(250); await pg.screenshot(path=str(OUT / f'{N[0]:02d}-{name}.png'), full_page=full)
async def js(pg, sel):
    ok = await pg.evaluate("(function(s){var e=document.querySelector(s); if(e) e.click(); return !!e})(%r)" % sel); await pg.wait_for_timeout(300); return ok
async def stage(pg): return await pg.inner_text('.sl-stephead')
async def nxt(pg): await js(pg, '[data-act="sl-next"]'); await pg.wait_for_timeout(200)
async def main():
    async with async_playwright() as p:
        b = await p.chromium.launch()
        ctx = await b.new_context(viewport={'width': 1024, 'height': 768}, has_touch=True); pg = await ctx.new_page(); errs = []
        pg.on("pageerror", lambda e: errs.append(str(e)))
        await pg.add_init_script("window.__role='manager'; window.print=function(){ window.__printed=(window.__printed||0)+1; };")
        await pg.goto((HERE / PAGE).as_uri()); await pg.wait_for_timeout(900)
        await pg.evaluate("try{localStorage.clear()}catch(e){}")
        await shot(pg, 'today')
        # 1. Take the order at the counter
        await js(pg, '#ccs-main .ccs-new, [data-tab="new"].ccs-newtop'); await pg.wait_for_timeout(500)
        check('New order opens from the button at the top right', 'Step 1 of 8' in await stage(pg))
        await js(pg, '[data-act="n-source"][data-v="walk_in"]')
        await js(pg, '[data-act="n-cell"][data-v="cheesecake|8"]'); await js(pg, '[data-act="n-finish"][data-v="custom"]')
        await pg.fill('#n-design', 'Blue ombre icing, gold leaf, number 30 topper'); await pg.wait_for_timeout(300)
        await shot(pg, 'step1-cake-custom-design')
        await nxt(pg); check('step 2 guest name', 'Step 2 of 8' in await stage(pg))
        await pg.fill('#n-name', 'Mere Tavola'); await shot(pg, 'step2-name'); await nxt(pg)
        await pg.fill('#n-phone', '912 3456'); await pg.wait_for_timeout(450); await js(pg, '[data-act="sl-opt"][data-v="yes"]'); await shot(pg, 'step3-contact'); await nxt(pg)
        check('step 4 pickup', 'Step 4 of 8' in await stage(pg))
        await js(pg, '#sl-st-3 .ccs-datechips [data-act="n-date"]:not(.ccs-chip-soon)'); await js(pg, '#sl-st-3 [data-act="n-time"][data-v="15:00"]')
        await shot(pg, 'step4-pickup'); await nxt(pg)
        check('step 5 candles and inscription', 'Step 5 of 8' in await stage(pg))
        await pg.fill('#n-candles', 'Number 30 candle'); await pg.fill('#n-msg', 'Happy 30th Mere'); await pg.wait_for_timeout(300); await shot(pg, 'step5-candles-inscription'); await nxt(pg)
        await js(pg, '[data-act="n-diet"][data-v="yes"]'); await js(pg, '[data-act="n-diets"][data-v="Nut allergy"]'); await shot(pg, 'step6-allergy'); await nxt(pg)
        check('step 7 remarks', 'Step 7 of 8' in await stage(pg))
        await js(pg, '[data-act="n-occ"][data-v="Birthday"]'); await pg.fill('#n-occfor', 'Mere'); await shot(pg, 'step7-remarks'); await nxt(pg)
        check('step 8 read over with the full slip beside it', 'Step 8 of 8' in await stage(pg) and 'Nut allergy' in await pg.inner_text('.sl-live') and 'Blue ombre' in await pg.inner_text('.sl-live'))
        await shot(pg, 'step8-read-over')
        await js(pg, '[data-act="n-submit"]'); await pg.wait_for_timeout(700)
        t = await pg.inner_text('#ccs-main')
        sent = await pg.evaluate("window.__calls.filter(function(c){return c[1]==='staff_create_order'}).map(function(c){return c[2].p})")
        x = sent[0] if sent else {}
        check('order saved once, with the details as taken', len(sent) == 1 and x.get('finish') == 'custom' and x.get('design', '').startswith('Blue ombre') and x.get('message') == 'Happy 30th Mere' and x.get('candles') == 'Number 30 candle' and x.get('dietary') == ['Nut allergy'] and (x.get('customer') or {}).get('opt_in') is True, x)
        check('saved screen gives the order number CC-1009 and says it needs a price', 'CC-1009' in t and ('quote' in t.lower() or 'needs' in t.lower()), t[:200])
        await shot(pg, 'saved')
        # 2. Price and confirm it
        check('after saving, back on Today with CC-1009 first under Needs attention', await pg.locator('#ccs-sheet.ccs-open').count() == 0 and 'CC-1009' in await pg.inner_text('.ccs-mini.is-new'))
        await js(pg, '.ccs-nav [data-tab="orders"]'); await pg.wait_for_timeout(600)
        t = await pg.inner_text('#ccs-main')
        check('Orders: it waits under Needs attention with its next action', 'CC-1009' in t and 'Give a price, then confirm' in t)
        await shot(pg, 'orders-needs-attention')
        await pg.evaluate("(function(){var c=[].slice.call(document.querySelectorAll('.ccs-card')).filter(function(x){return x.textContent.indexOf('CC-1009')>-1})[0]; c&&c.click()})()"); await pg.wait_for_timeout(700)
        check('order panel opens with the allergy in red at the top', 'Nut allergy' in await pg.inner_text('#ccs-sheet .ccs-alert'))
        await shot(pg, 'order-needs-quote')
        await js(pg, '#ccs-sheet [data-act="panel"][data-v="confirm"]'); await pg.fill('#ccs-price', '120'); await pg.fill('#ccs-dep', '50'); await shot(pg, 'quote-and-confirm')
        await js(pg, '#ccs-sheet [data-act="do-confirm"]'); await pg.wait_for_timeout(700)
        o = await pg.evaluate("window.__journey.order")
        check('confirmed at $120 with a $50 deposit asked', o['final_total'] == 120 and o['deposit_required'] == 50 and o['order_status'] == 'awaiting_deposit', (o['final_total'], o['deposit_required'], o['order_status']))
        # 3. Take the deposit
        await js(pg, '#ccs-sheet [data-act="panel"][data-v="pay"]'); await pg.fill('#ccs-amt', '50'); await js(pg, '#ccs-method [data-v="cash"], #ccs-method .ccs-chip'); await shot(pg, 'record-deposit')
        await js(pg, '#ccs-sheet [data-act="do-pay"]'); await pg.wait_for_timeout(700)
        o = await pg.evaluate("window.__journey.order")
        check('deposit recorded; order now confirmed, $70 to pay', o['order_status'] == 'confirmed' and o['payment_status'] == 'deposit_paid' and sum(float(p['amount']) for p in o['payments']) == 50, (o['order_status'], o['payment_status']))
        await shot(pg, 'confirmed-deposit-paid')
        # 4. Print the kitchen slip
        await js(pg, '#ccs-sheet [data-act="panel"][data-v="brief"]'); await js(pg, '#ccs-sheet [data-act="do-brief"][data-v="A5"]'); await pg.wait_for_timeout(900)
        await pg.evaluate("(function(){var e=document.querySelector('#ccs-sheet [data-act=brief-print]'); if(e) e.click()})()"); await pg.wait_for_timeout(700)
        title = await pg.evaluate("document.title"); slip = await pg.evaluate("(document.querySelector('#ccs-print .ccs-slip')||{}).innerText||''")
        check('slip printed: order number first, v1, file named for the order', await pg.evaluate("window.__printed||0") >= 1 and slip.strip().upper().startswith('ORDER') and 'CC-1009' in slip and re.match(r'^CC-1009 Pickup .+ Cheesecake 8 inch Mere Tavola v1$', title) is not None, title)
        check('slip carries allergy, design, inscription and candles', all(w in slip for w in ['Nut allergy', 'Blue ombre', 'Happy 30th Mere', 'Number 30 candle']), slip[:300])
        await pg.emulate_media(media='print'); await pg.pdf(path=str(OUT / 'kitchen-slip-CC-1009.pdf'), prefer_css_page_size=True, print_background=True); await pg.emulate_media(media='screen')
        await pg.evaluate("window.dispatchEvent(new Event('afterprint'))")
        # 5. Make it in the kitchen
        await js(pg, '#ccs-sheet [data-act="close"]'); await pg.wait_for_timeout(300)
        await pg.evaluate("(function(){var e=[].slice.call(document.querySelectorAll('[data-tab=kitchen]')).pop(); e&&e.click()})()"); await pg.wait_for_timeout(700)
        check('kitchen board shows the cake under To start', 'CC-1009' in await pg.inner_text('.ccs-col-start'))
        await shot(pg, 'kitchen-to-start')
        for _ in range(6):
            st = (await pg.evaluate("window.__journey.order.production_status"))
            if st == 'quality_check': break
            await pg.evaluate("(function(){var c=[].slice.call(document.querySelectorAll('.ccs-kitem')).filter(function(x){return x.textContent.indexOf('CC-1009')>-1})[0]; var b=c&&c.querySelector('[data-act=k-next]'); b&&b.click()})()"); await pg.wait_for_timeout(600)
        check('kitchen moved it step by step to quality check', await pg.evaluate("window.__journey.order.production_status") == 'quality_check')
        await shot(pg, 'kitchen-quality-check')
        await pg.evaluate("(function(){var c=[].slice.call(document.querySelectorAll('.ccs-kitem')).filter(function(x){return x.textContent.indexOf('CC-1009')>-1})[0]; var b=c&&c.querySelector('[data-act=open-kitchen]'); b&&b.click()})()"); await pg.wait_for_timeout(600)
        await js(pg, '#ccs-sheet [data-act="k-ready"]'); await pg.wait_for_timeout(400)
        check('Ready needs the name of who checked it', 'name' in (await pg.inner_text('#ccs-sheet')).lower() and await pg.evaluate("window.__journey.order.production_status") == 'quality_check')
        await pg.fill('#k-qc', 'Baker One'); await js(pg, '#ccs-sheet [data-act="k-ready"]'); await pg.wait_for_timeout(600)
        o = await pg.evaluate("window.__journey.order")
        check('marked Ready, checked by Baker One', o['production_status'] == 'ready' and o.get('qc_by') == 'Baker One')
        await js(pg, '#ccs-sheet [data-act="close"]'); await pg.wait_for_timeout(400)
        await shot(pg, 'kitchen-ready')
        # 6. Take the balance and hand over
        await pg.evaluate("(function(){var e=[].slice.call(document.querySelectorAll('[data-tab=orders]')).pop(); e&&e.click()})()"); await pg.wait_for_timeout(600)
        await js(pg, '[data-act="filter"][data-v="recent"]')
        await pg.evaluate("(function(){var c=[].slice.call(document.querySelectorAll('.ccs-card')).filter(function(x){return x.textContent.indexOf('CC-1009')>-1})[0]; c&&c.click()})()"); await pg.wait_for_timeout(700)
        dis = await pg.evaluate("(function(){var b=document.querySelector('#ccs-sheet [data-act=panel][data-v=collected]');return b?b.disabled:null})()")
        check('hand over stays locked while $70 is owing', dis is True, dis)
        await shot(pg, 'ready-balance-owing')
        await js(pg, '#ccs-sheet [data-act="panel"][data-v="pay"]'); await pg.fill('#ccs-amt', '70'); await js(pg, '#ccs-sheet [data-act="do-pay"]'); await pg.wait_for_timeout(700)
        o = await pg.evaluate("window.__journey.order")
        check('balance taken: paid in full', o['payment_status'] == 'paid')
        await js(pg, '#ccs-sheet [data-act="panel"][data-v="collected"]'); await pg.wait_for_timeout(300)
        await pg.fill('#ccs-note', 'Mere Tavola'); await shot(pg, 'hand-over')
        await js(pg, '#ccs-sheet [data-act="do-collected"]'); await pg.wait_for_timeout(700)
        o = await pg.evaluate("window.__journey.order")
        check('handed over to Mere Tavola; order Collected', o['order_status'] == 'completed' and o.get('handover_to') == 'Mere Tavola', (o['order_status'], o.get('handover_to')))
        await js(pg, '#ccs-sheet [data-act="secgo"][data-v="history"]'); await js(pg, '#ccs-sheet [data-act="history"]'); await pg.wait_for_timeout(300)
        h = await pg.inner_text('#ccs-sheet')
        check('history lists every step against CC-1009', all(w in h for w in ['Order placed', 'Accepted, waiting for', 'recorded', 'Kitchen slip v1', 'Kitchen:', 'Collected']), h[-600:])
        await shot(pg, 'collected-history')
        check('no page errors', not errs, errs)
        await b.close()
    print(f'{sum(R)}/{len(R)} passed')
asyncio.run(main())
